 INSERT INTO volunteer_entries(volunteer_user_id,event_edition_id,department_id,work_date,minutes_worked,work_description,status,submitted_at,decided_at,decided_by_user_id,decision_note) SELECT vol,event,reg,current_date,90,'Helped with badge preparation',s,CASE WHEN s='draft' THEN NULL ELSE now() END,CASE WHEN s IN ('approved','rejected') THEN now() ELSE NULL END,CASE WHEN s IN ('approved','rejected') THEN staff ELSE NULL END,CASE WHEN s='rejected' THEN 'Please clarify the activity description.' WHEN s='approved' THEN 'Thank you for helping!' ELSE NULL END FROM unnest(ARRAY['draft','submitted','approved','rejected','withdrawn']) s;
 INSERT INTO volunteer_decision_events(entry_id,actor_user_id,decision,note,method,idempotency_key) SELECT id,staff,status,decision_note,'manual',gen_random_uuid() FROM volunteer_entries WHERE volunteer_user_id=vol AND status IN ('approved','rejected');
