-- Deliberately called ONLY after development configuration is validated. Never seed on production boot.
CREATE FUNCTION seed_development() RETURNS void LANGUAGE plpgsql AS $$
DECLARE hr uuid; sys uuid; director uuid; lead uuid; staff uuid; staff2 uuid; vol uuid; vol2 uuid; applicant uuid; former uuid; div uuid; reg uuid; prog uuid; ops uuid; staff_level uuid; lead_level uuid; term uuid; ft uuid; fv uuid; post uuid; app uuid; interview uuid; event uuid;
BEGIN
 IF EXISTS(SELECT 1 FROM users WHERE dev_identity) THEN RETURN; END IF;
 SELECT id INTO staff_level FROM personnel_levels WHERE slug='staff'; SELECT id INTO lead_level FROM personnel_levels WHERE slug='lead';
 UPDATE users u SET primary_department_id=m.department_id FROM user_departments m WHERE m.user_id=u.id AND m.is_primary;
 UPDATE departments SET lead_user_id=lead WHERE id=reg; UPDATE divisions SET lead_user_id=director WHERE id=div;
END $$;
